from taf.selenium.mobile.sbts.provider import Provider


class SbtsFactory(object):

    @staticmethod
    def create(driver, download_checker, screenshot_dir, version=None):
        sbts_cls = Provider.provide(version)
        sbts = sbts_cls(driver, download_checker, screenshot_dir)
        return sbts
